import unittest
from rooms import can_book, free_slots, merge


class Regression(unittest.TestCase):
    def test_a_real_overlap_is_rejected(self):
        self.assertFalse(can_book([(9, 11)], (10, 12)))
        self.assertFalse(can_book([(9, 12)], (10, 11)))

    def test_touching_bookings_merge(self):
        self.assertEqual(merge([(9, 10), (10, 11)]), [(9, 11)])

    def test_a_full_day_has_no_free_slots(self):
        self.assertEqual(free_slots([(8, 17)], 8, 17), [])

    def test_no_empty_slot_when_the_last_meeting_ends_at_closing(self):
        self.assertEqual(free_slots([(9, 17)], 8, 17), [(8, 9)])

